import{_ as t,o as a,c as s,a2 as d}from"./chunks/framework.Y1x2IGEN.js";const u=JSON.parse('{"title":"API Reference","description":"Complete API reference for BITXpay cryptocurrency payment gateway.","frontmatter":{"title":"API Reference","description":"Complete API reference for BITXpay cryptocurrency payment gateway."},"headers":[],"relativePath":"api-reference/index.md","filePath":"api-reference/index.md","lastUpdated":1794835044000}'),i={name:"api-reference/index.md"};function n(r,e,o,c,l,p){return a(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="api-reference" tabindex="-1">API Reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to &quot;API Reference&quot;">​</a></h1><p>This is the complete API reference for BITXpay. All endpoints use HTTPS and return JSON responses.</p><h2 id="base-url" tabindex="-1">Base URL <a class="header-anchor" href="#base-url" aria-label="Permalink to &quot;Base URL&quot;">​</a></h2><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-ovYzB" id="tab-MOtHjTj" checked><label data-title="Production" for="tab-MOtHjTj">Production</label><input type="radio" name="group-ovYzB" id="tab-0dhIf5h"><label data-title="Sandbox" for="tab-0dhIf5h">Sandbox</label></div><div class="blocks"><div class="language-text vp-adaptive-theme active line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://api.bitxpay.com/api/v1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://sandboxapi.bitxpay.com/api/v1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></div></div><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>All merchant API requests must include signature authentication headers. Merchant endpoints (payment links and <code>/merchant/...</code> subscriptions) use <strong>Ed25519 (EdDSA) signature authentication</strong> (RSA-PSS accepted for legacy keys). See <a href="/api-reference/authentication">Authentication</a> for details.</p><p><strong>Merchant APIs (Ed25519 signature):</strong></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">X-API-Key:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> btxm_9b451fa04a2e</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # same format in sandbox and production</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">X-API-Signature:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">base64_encoded_ed25519_signatur</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">X-API-Timestamp:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2026-01-31T12:00:00Z</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Payer checkout routes under <code>/public/...</code> do not use merchant credentials. Dashboard APIs, including webhook management, use a dashboard session. Never embed your merchant private key in a checkout page.</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><h3 id="payments-merchant-api" tabindex="-1">Payments (Merchant API) <a class="header-anchor" href="#payments-merchant-api" aria-label="Permalink to &quot;Payments (Merchant API)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Endpoint</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/payment_links/currencies</code></td><td>Get currencies; optionally filter by <code>currency_type=fiat</code> or <code>crypto</code></td></tr><tr><td><code>GET</code></td><td><code>/payment_links/catalog</code></td><td>Discover available checkout chains, tokens, and settlement currencies</td></tr><tr><td><code>GET</code></td><td><code>/payment_links</code></td><td>List all payment links</td></tr><tr><td><code>POST</code></td><td><code>/payment_links</code></td><td>Create a payment link</td></tr><tr><td><code>GET</code></td><td><code>/payment_links/:id</code></td><td>Get payment link by ID</td></tr><tr><td><code>PUT</code></td><td><code>/payment_links/:id/status</code></td><td>Deactivate or expire a payment link</td></tr><tr><td><code>DELETE</code></td><td><code>/payment_links/:id</code></td><td>Soft-delete a payment link</td></tr></tbody></table><h3 id="subscriptions-—-authenticated-merchant-routes" tabindex="-1">Subscriptions — Authenticated (Merchant) Routes <a class="header-anchor" href="#subscriptions-—-authenticated-merchant-routes" aria-label="Permalink to &quot;Subscriptions — Authenticated (Merchant) Routes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Endpoint</th><th>Description</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/merchant/subscription_plans/</code></td><td>Create a subscription plan</td></tr><tr><td><code>GET</code></td><td><code>/merchant/subscription_plans/</code></td><td>List subscription plans</td></tr><tr><td><code>GET</code></td><td><code>/merchant/subscription_plans/:id</code></td><td>Get subscription plan by ID</td></tr><tr><td><code>PUT</code></td><td><code>/merchant/subscription_plans/:id</code></td><td>Update a subscription plan</td></tr><tr><td><code>POST</code></td><td><code>/merchant/subscribers/</code></td><td>Create a subscriber</td></tr><tr><td><code>GET</code></td><td><code>/merchant/subscribers/</code></td><td>Get subscribers by merchant</td></tr><tr><td><code>GET</code></td><td><code>/merchant/subscribers/plan/:plan_id</code></td><td>Get subscribers by plan ID</td></tr><tr><td><code>PUT</code></td><td><code>/merchant/subscribers/:id</code></td><td>Update a subscriber</td></tr><tr><td><code>GET</code></td><td><code>/merchant/subscribers/:id</code></td><td>Get subscriber by ID</td></tr><tr><td><code>GET</code></td><td><code>/merchant/subscribers/invitations</code></td><td>Get merchant invitations</td></tr><tr><td><code>GET</code></td><td><code>/merchant/subscription_links/</code></td><td>List subscription links</td></tr><tr><td><code>GET</code></td><td><code>/merchant/subscription_links/:id</code></td><td>Get subscription link by ID</td></tr></tbody></table><p>These routes require Merchant API Key authentication (<code>X-API-Key</code>/<code>X-API-Signature</code> with Ed25519), same as the Payments API.</p><h3 id="subscriptions-—-public-routes" tabindex="-1">Subscriptions — Public Routes <a class="header-anchor" href="#subscriptions-—-public-routes" aria-label="Permalink to &quot;Subscriptions — Public Routes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Endpoint</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/public/subscriptions/plans/</code></td><td>List public subscription plans</td></tr><tr><td><code>GET</code></td><td><code>/public/subscriptions/plans/:id</code></td><td>Get public subscription plan by ID</td></tr><tr><td><code>GET</code></td><td><code>/public/subscriber/prepare</code></td><td>Prepare subscription enrollment</td></tr><tr><td><code>GET</code></td><td><code>/public/subscriber/:id</code></td><td>Get subscriber by ID</td></tr><tr><td><code>PUT</code></td><td><code>/public/subscriber/:id</code></td><td>Update subscriber</td></tr><tr><td><code>POST</code></td><td><code>/public/subscriptions/link/</code></td><td>Create a subscription link</td></tr><tr><td><code>GET</code></td><td><code>/public/subscriptions/link/:walletAddress</code></td><td>Get subscription links by wallet address</td></tr><tr><td><code>POST</code></td><td><code>/public/subscriptions/link/payment</code></td><td>Record a subscription payment</td></tr><tr><td><code>PUT</code></td><td><code>/public/subscriptions/link/:id</code></td><td>Update a subscription link</td></tr><tr><td><code>GET</code></td><td><code>/public/subscriptions/nft/:plan_id</code></td><td>Get subscription NFT metadata</td></tr></tbody></table><p>These routes do not require merchant signature headers — they are called directly from the customer-facing wallet/checkout flow. See <a href="/api-reference/subscriptions">Subscriptions</a> for full request/response details.</p><h3 id="payments-—-public-checkout" tabindex="-1">Payments — Public Checkout <a class="header-anchor" href="#payments-—-public-checkout" aria-label="Permalink to &quot;Payments — Public Checkout&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Endpoint</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/public/payments/links/:id</code></td><td>Get payer-facing payment link details</td></tr><tr><td><code>GET</code></td><td><code>/public/payments/links/:id/validate</code></td><td>Validate a payment link</td></tr><tr><td><code>GET</code></td><td><code>/public/payments/engine/links/:id/options</code></td><td>Get available network/token choices</td></tr><tr><td><code>POST</code></td><td><code>/public/payments/engine/links/:id/quote</code></td><td>Select or refresh a payment quote</td></tr><tr><td><code>GET</code></td><td><code>/public/payments/engine/links/:id/state</code></td><td>Poll order status and confirmations</td></tr></tbody></table><p>The engine checkout routes are mounted only when configured and enabled. See <a href="/api-reference/checkout">Checkout</a> for request and response details.</p><h3 id="webhook-management-—-dashboard-session" tabindex="-1">Webhook Management — Dashboard Session <a class="header-anchor" href="#webhook-management-—-dashboard-session" aria-label="Permalink to &quot;Webhook Management — Dashboard Session&quot;">​</a></h3><p>Webhook configuration uses <code>/webhooks</code> with dashboard authentication. See <a href="/api-reference/webhooks">Webhook Management</a> for every method, request/response, shared-secret behavior, polling, and test events. The <a href="/api-reference/webhook-events">Webhook Event Data reference</a> documents all typed event payloads with field tables, examples, and a downloadable JSON Schema.</p><p>The generated <a href="/api-reference/data-models">Request and Response Fields</a> reference tracks exact names, JSON types, serialization tags, and declared constraints for the current models, including public checkout and webhook management.</p><p>The generated <a href="/api-reference/public-api-routes">Route Inventory</a> lists the registered integration routes and their authentication boundaries, including legacy checkout, metadata, contact/assets, development helpers, and the session-protected mass-payout group.</p><h2 id="response-format" tabindex="-1">Response Format <a class="header-anchor" href="#response-format" aria-label="Permalink to &quot;Response Format&quot;">​</a></h2><p>Merchant payment and subscription controllers generally return <code>message</code> and <code>data</code>:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Payment link created successfully&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;22222222-2222-2222-2222-222222222222&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;payment_status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;processing&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Message-only responses omit <code>data</code>. Payment list results nest records at <code>data.data</code> and pagination at <code>data.pagination</code>. Subscription lists wrap their endpoint-specific list object in <code>data</code>. The checkout catalog, engine payer routes, and subscription prepare response are unwrapped JSON objects.</p><h2 id="error-handling" tabindex="-1">Error Handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error Handling&quot;">​</a></h2><p>Use the HTTP status as the primary error indicator. Merchant controller errors generally return a message:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Invalid payment link ID&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Authentication middleware also returns <code>error</code> and a <strong>string</strong> <code>code</code>, such as <code>SIGNATURE_VERIFICATION_FAILED</code>. Engine errors may return <code>error</code> and <code>code</code>; do not assume a numeric <code>code</code> or a uniform error envelope for every route.</p><h3 id="error-codes" tabindex="-1">Error Codes <a class="header-anchor" href="#error-codes" aria-label="Permalink to &quot;Error Codes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Description</th></tr></thead><tbody><tr><td><code>400</code></td><td>Bad Request - Invalid parameters</td></tr><tr><td><code>401</code></td><td>Unauthorized - Invalid API key</td></tr><tr><td><code>403</code></td><td>Forbidden - Insufficient permissions</td></tr><tr><td><code>404</code></td><td>Not Found - Resource doesn&#39;t exist</td></tr><tr><td><code>429</code></td><td>Too Many Requests - Rate limit exceeded</td></tr><tr><td><code>500</code></td><td>Internal Server Error</td></tr></tbody></table><h2 id="rate-limits" tabindex="-1">Rate Limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to &quot;Rate Limits&quot;">​</a></h2><p>Rate limits are attached to individual routes. In this backend checkout, payment/default limiters are configured to 100 requests per minute. Merchant payment create/currency/catalog routes attach a limiter; list/get/status/delete do not attach a separate endpoint limiter. Subscription routes attach payment/default limiters. Limiter identity uses recognized user/API-key context, falling back to the client IP.</p><p>Handle HTTP <code>429</code>, honor <code>Retry-After</code> when present, and use response rate-limit headers when available. Global middleware or infrastructure can impose additional limits; the backend does not define separate sandbox/production account ceilings of 100/1000 requests per minute.</p>`,38)])])}const b=t(i,[["render",n]]);export{u as __pageData,b as default};
